<script lang="ts">
  import { createQuery, createInfiniteQuery, createMutation, useQueryClient } from "@tanstack/svelte-query";
  import { reactiveOptions } from "$lib/components/projects/reactive-options.svelte";
  import { page } from "$app/stores";
  import { goto } from "$app/navigation";
  import { base } from "$app/paths";
  import { authStore } from "$lib/stores/auth";
  import { workflowsApi, workflowKeys } from "$lib/api/workflows";
  import { PageShell, StateBlock, Section, Timestamp, SaveState } from "$lib/components/page";
  import { Button } from "$lib/components/ui/button";
  import { Textarea } from "$lib/components/ui/textarea";
  import { FormField } from "$lib/components/ui/form-field";
  import WorkflowEditor from "$lib/components/workflows/WorkflowEditor.svelte";
  import WorkflowRunForm from "$lib/components/workflows/WorkflowRunForm.svelte";
  import WorkflowMarkdown from "$lib/components/workflows/WorkflowMarkdown.svelte";
  import WorkflowAvailability from "$lib/components/workflows/WorkflowAvailability.svelte";
  import WorkflowStatus from "$lib/components/workflows/WorkflowStatus.svelte";
  import WorkflowVersionDiff from "$lib/components/workflows/WorkflowVersionDiff.svelte";
  import { safeWorkflowUrl } from "$lib/components/workflows/helpers";
  const canRead = $derived($authStore.can("workflows.read")), canManage = $derived($authStore.can("workflows.manage")), canRun = $derived($authStore.can("workflows.run"));
  const slug = $derived($page.params.slug ?? ""), selected = $derived(Number($page.url.searchParams.get("version")) || undefined), mode = $derived($page.url.searchParams.get("mode") ?? "view");
  const current = createQuery(reactiveOptions(() => ({ queryKey: workflowKeys.definition(slug), queryFn: () => workflowsApi.get(slug), enabled: canRead })));
  const historical = createQuery(reactiveOptions(() => ({ queryKey: workflowKeys.definition(slug, selected), queryFn: () => workflowsApi.get(slug, selected), enabled: canRead && !!selected })));
  const versions = createInfiniteQuery(reactiveOptions(() => ({ queryKey: workflowKeys.versions(slug), queryFn: ({ pageParam }: { pageParam: string | undefined }) => workflowsApi.versions(slug, pageParam), initialPageParam: undefined as string | undefined, getNextPageParam: (last: { next_cursor: string | number | null }) => last.next_cursor == null ? undefined : String(last.next_cursor), enabled: canRead })));
  const shown = $derived(canRead ? (selected ? $historical.data : $current.data) : undefined), client = useQueryClient();
  let reason = $state(""), request = $state<{ fingerprint: string; id: string } | null>(null);
  const change = createMutation({ mutationFn: (action: "archive" | "restore" | "revert") => {
    const d = $current.data!, fingerprint = JSON.stringify({ action, reason, selected, version: d.version, control: d.control_version });
    if (request?.fingerprint !== fingerprint) request = { fingerprint, id: crypto.randomUUID() };
    const body = { client_request_id: request!.id, expected_workflow_version: d.version, reason };
    return action === "revert" ? workflowsApi.revert(d.workflow_id, { ...body, version: selected! }) : workflowsApi.archive(d.workflow_id, { ...body, expected_control_version: d.control_version }, action === "restore");
  }, onSuccess: async () => { request = null; reason = ""; await client.invalidateQueries({ queryKey: workflowKeys.all }); await setView({ version: "", mode: "view" }); } });
  function setView(values: Record<string, string>) { const url = new URL($page.url); for (const [k,v] of Object.entries(values)) v ? url.searchParams.set(k,v) : url.searchParams.delete(k); return goto(url.pathname + url.search, { noScroll: true, keepFocus: true }); }
</script>
<PageShell title={shown?.document.title ?? "Workflow definition"} description={shown?.document.summary} width={mode === "edit" ? "narrow" : "default"}>
  {#snippet actions()}<Button href={`${base}/workflows`} variant="outline">Back to workflows</Button>{#if shown}<Button href={`${base}/workflows/runs?workflow_id=${shown.workflow_id}`} variant="outline">Workflow runs</Button>{#if canRun && $current.data?.enabled && $current.data.status === "active"}<Button onclick={() => setView({ mode: mode === "run" ? "view" : "run" })}>{mode === "run" ? "View definition" : "New run"}</Button>{/if}{/if}{/snippet}
  {#if !canRead}<StateBlock state="empty" message="Workflow access required" />{:else if $current.isPending || (selected && $historical.isPending)}<StateBlock state="loading" />{:else if $current.isError || (selected && $historical.isError)}<StateBlock state="error" message={shown ? "Refresh failed. Showing previously loaded definition; it may be stale." : $current.error?.message ?? $historical.error?.message ?? "Could not load workflow."} onRetry={() => { void $current.refetch(); if (selected) void $historical.refetch(); }} />{/if}
  {#if shown}
    <WorkflowAvailability />
    <div class="flex flex-wrap items-center gap-3 text-body-sm"><WorkflowStatus value={$current.data?.status} /><span>Version {shown.version}{selected ? " · Historical version" : " · Current head"}</span><Timestamp value={shown.created_at} />{#if !$current.data?.enabled}<span>Module disabled; history remains readable.</span>{/if}{#if mode !== "edit" && !selected && canManage}<Button variant="outline" size="sm" onclick={() => setView({ mode: "edit" })}>Edit workflow</Button>{/if}{#if mode === "edit"}<Button variant="outline" size="sm" onclick={() => setView({ mode: "view" })}>View definition</Button>{/if}</div>
    {#if mode === "edit" && !selected}<WorkflowEditor definition={shown} {canManage} enabled={$current.data?.enabled ?? false} />{:else if mode === "run"}<Section title="Prepare a run"><WorkflowRunForm definition={shown} allowed={canRun && !!$current.data?.enabled && $current.data.status === "active"} /></Section>{:else}
      <Section title="Goal"><WorkflowMarkdown text={shown.document.goal.statement} /><ul class="mt-3 space-y-2">{#each shown.document.goal.success_criteria as c}<li class="flex gap-2 text-body"><span aria-hidden="true">•</span><span>{c.text}</span></li>{/each}</ul></Section>
      <Section title="Tasks"><ol class="divide-y">{#each shown.document.tasks as task, i (task.id)}<li class="py-4 first:pt-0"><h3 class="text-body font-semibold">{i + 1}. {task.title}</h3><div class="mt-2"><WorkflowMarkdown text={task.instructions} /></div><p class="mt-2 text-body-sm text-muted-foreground">{task.depends_on.length ? `After: ${task.depends_on.map(id => shown!.document.tasks.find(t => t.id === id)?.title ?? id).join(", ")}` : "Independent task"}</p>{#if task.execution_hint}<p class="mt-1 text-body-sm">Access: {task.execution_hint}</p>{/if}<details class="mt-2 text-body-sm"><summary class="cursor-pointer py-1">Acceptance criteria and knowledge</summary><ul class="list-inside list-disc">{#each task.acceptance_criteria as c}<li>{c}</li>{/each}</ul>{#each task.knowledge_ids as id}<p>{shown.document.knowledge.find(k => k.id === id)?.title ?? id}</p>{/each}</details></li>{/each}</ol></Section>
      <Section title="Knowledge">{#if !shown.document.knowledge.length}<p class="text-body-sm text-muted-foreground">No knowledge sources required.</p>{/if}{#each shown.document.knowledge as source}<details class="border-b py-3"><summary class="cursor-pointer text-body font-medium">{source.title}</summary><div class="mt-2">{#if source.reference}{#if safeWorkflowUrl(source.reference.uri)}<a class="break-all text-body underline" href={safeWorkflowUrl(source.reference.uri)!} rel="noopener noreferrer" target="_blank">{source.reference.uri}</a>{:else}<code class="break-all text-body-sm">{source.reference.uri}</code>{/if}{#if source.reference.read_hint}<p class="mt-2 text-body-sm">{source.reference.read_hint}</p>{/if}{:else}<WorkflowMarkdown text={source.inline ?? ""} />{/if}</div></details>{/each}</Section>
    {/if}
    {#if mode !== "edit"}<Section title="Versions and changes"><div class="space-y-3"><label class="block text-body font-medium" for="workflow-version">View published version</label><select id="workflow-version" class="h-9 max-w-full rounded border border-input bg-background px-2 text-body" value={selected ?? ""} onchange={e => setView({ version: e.currentTarget.value, mode: "view" })}><option value="">Current head · {$current.data?.version}</option>{#each $versions.data?.pages.flatMap(p => p.items) ?? [] as version}<option value={version.version}>Version {version.version} · {version.reason}</option>{/each}</select>{#if $versions.hasNextPage}<Button variant="outline" size="sm" disabled={$versions.isFetchingNextPage} onclick={() => $versions.fetchNextPage()}>More versions</Button>{/if}{#if $versions.isError}<StateBlock state="error" message="Could not load version history." onRetry={() => $versions.refetch()} />{/if}<p class="text-body-sm">{shown.reason}</p><WorkflowVersionDiff diff={shown.diff ?? $versions.data?.pages.flatMap(p => p.items).find(v => v.version === shown!.version)?.diff} />{#if shown.source_run_id}<a class="text-body-sm underline" href={`${base}/workflows/runs/${shown.source_run_id}`}>Evaluation that published this version</a>{/if}<details class="text-body-sm"><summary class="cursor-pointer">Version digest</summary><code class="break-all">{shown.sha256}</code></details></div></Section>
      {#if canManage && $current.data}<Section title="Version management" danger description="History is preserved. Restoring an older version publishes a new version; archiving blocks new runs."><FormField id="workflow-management-reason" label="Reason" required><Textarea id="workflow-management-reason" bind:value={reason} /></FormField><div class="mt-3 flex flex-wrap gap-2">{#if selected && selected !== $current.data.version}<Button variant="outline" disabled={!reason.trim() || $change.isPending} onclick={() => $change.mutate("revert")}>Restore version {selected} as new version</Button>{/if}<Button variant="outline" disabled={!reason.trim() || $change.isPending} onclick={() => $change.mutate($current.data!.status === "archived" ? "restore" : "archive")}>{$current.data.status === "archived" ? "Unarchive workflow" : "Archive workflow"}</Button></div>{#if $change.error}<SaveState error={$change.error} />{/if}</Section>{/if}
    {/if}
  {/if}
</PageShell>
